-- E28 black-box fixture set (E28-Q01, #904): the database seed. Every row is synthetic (README.md):
-- no key, UID, label or balance of a real account, and no `api_keys` row at all.
-- Load it into a clean test database migrated to head, from the repository root:
--   psql -v ON_ERROR_STOP=1 "$DATABASE_URL" -f tests/fixtures/e28/seed.sql
-- One transaction: a failure writes nothing, and so does a second run (its first primary key).
-- Each table's rows are one JSON array that pg_temp.e28_insert writes column for column (a row's
-- keys are the columns, alike in every row; a column left out takes its default), so that
-- services/api/tests/unit/accounts/test_e28_fixture_set.py checks every row's columns against the
-- models.
BEGIN;

DO $guard$
BEGIN
  IF current_database() !~ '^(test|.+_test)$' THEN
    RAISE EXCEPTION 'e28 seed refused: % is not a test database', current_database();
  END IF;
END
$guard$;

CREATE FUNCTION pg_temp.e28_insert(tbl regclass, payload jsonb) RETURNS void
LANGUAGE plpgsql AS $fn$
DECLARE cols text;
BEGIN
  SELECT string_agg(quote_ident(k), ', ') INTO cols FROM jsonb_object_keys(payload -> 0) AS k;
  EXECUTE format('INSERT INTO %s (%s) SELECT %s FROM jsonb_populate_recordset(NULL::%s, $1)',
                 tbl, cols, cols, tbl) USING payload;
END
$fn$;

-- The Owner who made the accounts and fired the groups; its hash verifies no password.
SELECT pg_temp.e28_insert('users', $users$[
{"id": "e28f0000-0000-4000-8000-000000000001", "email": "fx-e28-owner@example.invalid", "username": "fx-e28-owner", "status": "active", "password_hash": "$argon2id$v=19$m=65536,t=3,p=4$fixture-salt$no-password-matches"}
]$users$);
INSERT INTO user_roles (user_id, role_id)
SELECT 'e28f0000-0000-4000-8000-000000000001', id FROM roles WHERE name = 'owner';

