-- Each demo account's bootstrap `Default` (trg_ea_default_profile) gives way to its E28 profile:
-- soft-deleted and no longer the default, then the E28 profile goes in as the default. A move
-- made this way leaves default_binding_version at 1 (21 §3.2.4); no binding tag exists yet.
-- The live accounts keep their inert bootstrap `Default`.
UPDATE account_profiles
SET is_default = false, deleted_at = now(), updated_by = 'e28f0000-0000-4000-8000-000000000001'
WHERE name = 'Default' AND deleted_at IS NULL AND exchange_account_id IN (
  'e28f0000-0000-4000-8000-0000000000d1', 'e28f0000-0000-4000-8000-0000000000d2',
  'e28f0000-0000-4000-8000-0000000000d3', 'e28f0000-0000-4000-8000-0000000000d4');

